[{'runs_on': 'ubuntu-latest', 'steps': [{'name': 'Download artifact', 'uses': 'actions/github-script@v7', 'with': {'script': 'let allArtifacts = await github.rest.actions.listWorkflowRunArtifacts({
   owner: context.repo.owner,
   repo: context.repo.repo,
   run_id: context.payload.workflow_run.id,
});
let matchArtifact = allArtifacts.data.artifacts.filter((artifact) => {
  return artifact.name == "pr_number"
})[0];
let download = await github.rest.actions.downloadArtifact({
   owner: context.repo.owner,
   repo: context.repo.repo,
   artifact_id: matchArtifact.id,
   archive_format: 'zip',
});
const fs = require('fs');
fs.writeFileSync('${{github.workspace}}/pr_number.zip', Buffer.from(download.data));
'}}, {'name': 'Unzip artifact', 'run': 'unzip pr_number.zip'}, {'name': 'Get PR number', 'run': 'echo "number=$(cat NR)" >> $GITHUB_OUTPUT', 'id': 'pr-number'}, {'name': 'Find Comment', 'uses': 'peter-evans/find-comment@v2', 'id': 'pr-comment', 'with': {'issue-number': '${{ steps.pr-number.outputs.number }}', 'comment-author': 'github-actions[bot]', 'body-includes': 'Added or changed icons'}}, {'name': 'Create or update comment', 'uses': 'peter-evans/create-or-update-comment@v3', 'with': {'comment-id': '${{ steps.pr-comment.outputs.comment-id }}', 'issue-number': '${{ steps.pr-number.outputs.number }}', 'body-path': 'comment-markup.md', 'edit-mode': 'replace'}}], 'matrix_combinations': 1}]

[{'runs_on': 'ubuntu-latest', 'steps': [{'uses': 'actions/checkout@v4'}, {'run': 'npm install'}, {'run': 'npm run build --if-present'}, {'run': 'npm run test-ci'}], 'matrix_combinations': 1}, {'runs_on': 'ubuntu-latest', 'steps': [{'uses': 'actions/checkout@v4'}, {'uses': 'actions/setup-node@v4', 'with': {'node-version': 24, 'registry-url': 'https://npm.pkg.github.com/'}}, {'name': 'Insert repository owner as scope into package name', 'run': 'node <<EOF
const fs = require('fs').promises;
fs.readFile('package.json', 'utf8').then((data) => JSON.parse(data)).then((json) => {
  json.name = '@$(echo "$GITHUB_REPOSITORY" | sed 's/\/.\+//')/' + json.name;
  console.info('Package name changed to %s', json.name);
  return fs.writeFile('package.json', JSON.stringify(json), 'utf8');
}).catch(error => {
  console.error(error);
  process.exit(1);
});
EOF
'}, {'run': 'npm install'}, {'run': 'npm publish', 'env': {'NODE_AUTH_TOKEN': '${{secrets.GITHUB_TOKEN}}'}}], 'matrix_combinations': 1}]

[{'runs_on': 'ubuntu-latest', 'steps': [{'name': 'Checkout repository', 'uses': 'actions/checkout@v4'}, {'name': 'Get list of orphans', 'uses': 'actions/github-script@v7', 'id': 'orphans', 'with': {'github-token': '${{ secrets.GITHUB_TOKEN }}', 'script': "const query = `query($owner:String!, $name:String!) {
  repository(owner:$owner, name:$name){
    pullRequests(first: 100, states: OPEN){
      nodes{
        title
        url
        author {
          resourcePath
        }
      }
    }
  }
}`;
const variables = {
  owner: context.repo.owner,
  name: context.repo.repo
};
const { repository: { pullRequests: { nodes } } } = await github.graphql(query, variables);

let orphans = nodes.filter( (pr) => pr.author.resourcePath === '/asyncapi-bot' || pr.author.resourcePath === '/apps/dependabot')

if (orphans.length) {
  core.setOutput('found', 'true');
  //Yes, this is very naive approach to assume there is just one PR causing issues, there can be a case that more PRs are affected the same day
  //The thing is that handling multiple PRs will increase a complexity in this PR that in my opinion we should avoid
  //The other PRs will be reported the next day the action runs, or person that checks first url will notice the other ones
  core.setOutput('url', orphans[0].url);
  core.setOutput('title', orphans[0].title);
}
"}}, {'if': "steps.orphans.outputs.found == 'true'", 'name': 'Convert markdown to slack markdown', 'uses': 'asyncapi/.github/.github/actions/slackify-markdown@master', 'id': 'issuemarkdown', 'with': {'markdown': '-> [${{steps.orphans.outputs.title}}](${{steps.orphans.outputs.url}})'}}, {'if': "steps.orphans.outputs.found == 'true'", 'name': 'Send info about orphan to slack', 'uses': 'rtCamp/action-slack-notify@c33737706dea87cd7784c687dadc9adf1be59990', 'env': {'SLACK_WEBHOOK': '${{secrets.SLACK_CI_FAIL_NOTIFY}}', 'SLACK_TITLE': '🚨 Not merged PR that should be automerged 🚨', 'SLACK_MESSAGE': '${{steps.issuemarkdown.outputs.text}}', 'MSG_MINIMAL': True}}], 'matrix_combinations': 1}]

