[{'runs_on': 'ubuntu-latest', 'steps': [{'name': 'Get PR comments count', 'id': 'get_comments', 'uses': 'actions/github-script@v7', 'with': {'script': 'let prNumber;
let totalComments = 0;

if (context.eventName === 'pull_request') {
  prNumber = context.payload.pull_request.number;
