[{'runs_on': 'ubuntu-latest', 'steps': [{'name': 'content template', 'id': 'template', 'run': 'contribute="详见：🍀 [Layui Issue 贡献指南](https://github.com/layui/layui/blob/main/CONTRIBUTING.md)"
