  spec_path="${specs[$api]}"
  mkdir -p "docs/$api"
  echo "🔧 Bundling $api..."
  # Capture stderr from bundling
  BUNDLE_ERR=$(npx redocly bundle "$spec_path" -o "docs/$api/$api.api.consolidated.v1.json" 2>&1)
