[{'runs_on': 'ubuntu-latest', 'steps': [{'uses': 'actions/github-script@v7', 'id': 'sanitize-title', 'with': {'script': 'const isPR = !!context.payload.pull_request;
const isIssue = !!context.payload.issue;
const item = isPR ? context.payload.pull_request : isIssue ? context.payload.issue : context.payload.issue_comment.issue;

// Sanitization functions
const sanitizeTitle = (title) => {
  return title
    // Remove potential markdown formatting
    .replace(/[*_~`]/g, '')
    // Remove potential HTML tags
    .replace(/<[^>]*>/g, '')
    // Remove multiple spaces
    .replace(/\s{2,}/g, ' ')
    // Trim whitespace
    .trim()
    // Enforce max length of 100
    .substring(0, 100);
};

// Escape special characters for Slack
const escapeForSlack = (text) => {
  return text
    .replace(/"/g, '&quot;')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/[@]/g, '\\@')
    .replace(/>/g, '&gt;')
    .replace(/&amp;lt;/g, '&lt;')
    .replace(/&amp;gt;/g, '&gt;');
};

const sanitizedTitle = escapeForSlack(sanitizeTitle(item.title));
console.log('Sanitized Title: ', sanitizedTitle);
core.setOutput('safe-title', sanitizedTitle);
'}}, {'name': 'Send notifications on Pull Request', 'if': "${{ github.event_name == 'pull_request'}}", 'id': 'slack_PR', 'uses': 'slackapi/slack-github-action@v1.26.0', 'with': {'payload': '{
